<?php require_once __DIR__.'/includes/ui.php';
$all=public_videos();$q=trim((string)($_GET['q']??''));$cat=trim((string)($_GET['category']??''));$sort=(string)($_GET['sort']??'newest');
$categories=[];foreach($all as $v){$category=trim($v['category']??'');if($category!=='')$categories[$category]=true;}ksort($categories);
$list=array_values(array_filter($all,function($v)use($q,$cat){$c=creator_for($v);$search=implode(' ',[$v['title']??'',$v['description']??'',$v['owner_name']??'',$v['tags']??'',$c['name']??'']);return (!$q || mb_search($search,$q)) && (!$cat || ($v['category']??'')===$cat); }));
function mb_search($hay,$needle): bool {return function_exists('mb_stripos')?mb_stripos($hay,$needle)!==false:stripos($hay,$needle)!==false;}
usort($list,match($sort){'popular'=>fn($a,$b)=>($b['views']??0)<=>($a['views']??0),'oldest'=>fn($a,$b)=>strcmp($a['display_date']??'',$b['display_date']??''),'title'=>fn($a,$b)=>strcasecmp($a['title']??'',$b['title']??''),default=>fn($a,$b)=>strcmp($b['display_date']??'',$a['display_date']??'')});
head_meta('Explore', 'Khám phá thư viện video và nhà sáng tạo.');header_ui($sort==='popular'?'popular':($sort==='newest'?'explore':'explore')); ?>
<div class="page-intro"><div class="section-index">THE LIBRARY / DISCOVER</div><h1>Khám phá <span class="header-dot">.</span></h1><p>Không gian cho những tác phẩm video độc lập.</p></div>
<form class="filter-toolbar" method="get" action="<?=h(path_url('explore.php'))?>"><label class="filter-input"><?=icon('search',18)?><input name="q" value="<?=h($q)?>" placeholder="Tìm tiêu đề, creator, tags..."></label><select name="category" aria-label="Danh mục"><option value="">Tất cả danh mục</option><?php foreach(array_keys($categories) as $cc):?><option value="<?=h($cc)?>" <?=$cat===$cc?'selected':''?>><?=h($cc)?></option><?php endforeach?></select><select name="sort" aria-label="Sắp xếp"><option value="newest" <?=$sort==='newest'?'selected':''?>>Mới nhất</option><option value="popular" <?=$sort==='popular'?'selected':''?>>Nhiều lượt xem</option><option value="oldest" <?=$sort==='oldest'?'selected':''?>>Cũ nhất</option><option value="title" <?=$sort==='title'?'selected':''?>>A → Z</option></select><button class="btn btn-primary" type="submit">Áp dụng <?=icon('arrow-right',17)?></button></form>
<div class="result-count"><?=count($list)?> VIDEO <?= $q ? '· Tìm kiếm “'.h($q).'”' : '' ?></div>
<?php if($list):?><div class="video-grid"><?php foreach($list as $v)video_card($v);?></div><?php else:?><?php empty_content('Không tìm thấy video','Hãy thử từ khóa khác hoặc thay đổi bộ lọc.');?><?php endif?>
<?php footer_ui(); ?>
